-- 从 schema.sql 终态导出的 PostgreSQL 技能树静态快照。
-- 当前只做 upsert，不主动删除旧 PG pilot 中已存在的静态 seed，
-- 以避免在已有实验数据时误伤 skill_progress 等依赖链。

ON CONFLICT (node_code) DO UPDATE SET
    label = EXCLUDED.label,
    description = EXCLUDED.description,
    parent_code = EXCLUDED.parent_code,
    sort_order = EXCLUDED.sort_order,
    updated_at = EXCLUDED.updated_at;

ON CONFLICT (source_node_code, target_node_code, relation_type) DO UPDATE SET
    label = EXCLUDED.label,
    sort_order = EXCLUDED.sort_order,
    updated_at = EXCLUDED.updated_at;

ON CONFLICT (resource_code) DO UPDATE SET
    node_code = EXCLUDED.node_code,
    resource_type = EXCLUDED.resource_type,
    title = EXCLUDED.title,
    source_label = EXCLUDED.source_label,
    duration_label = EXCLUDED.duration_label,
    link_url = EXCLUDED.link_url,
    sort_order = EXCLUDED.sort_order,
    updated_at = EXCLUDED.updated_at;
